	halloc := func(n int) uint32 {
		off := uint32(g.hElems)
		g.hElems += (n + 63) &^ 63
		return off
	}
	// One row past the batch, because that is where a padding row's
	// permutation entry points and it has to be zero.
	g.hXn = halloc((rows + moeBMMax) * g.lda)
	g.hSwiglu = halloc(maxRows * g.ldCtx)
	if g.hbuf, err = newArena(g.dev, g.hElems*2); err != nil {
		return fmt.Errorf("llm: moe fp16 activation arena (%d MB): %w", (g.hElems*2)>>20, err)
	}
	// Zeroed once: the A operands' pad columns, the sentinel token's row and
	// every swiglu row no tile ever writes. None of these kernels
	// bounds-checks, and a stale half can be a NaN.
	g.hbuf.Zero()
	g.abuf.Zero()

=== gemmPad ===
780:		lda:        cfg.NEmbd + gemmPad,
781:		ldCtx:      cfg.FFNExpert + gemmPad,

input.command:
python3 - <<'PY'
p='llm/gpu_moe.go'
s=open(p).read()
old = """	// The last two bindings are **arrays** of moeMaxBanks descriptors, one a
	// layer, so the seven bindings are 5 + 2*48 = 101 buffers (L6a).
	banks := g.bankSet()
	bufs := append([]*vk.Buffer{g.wbuf, g.abuf, g.hbuf, g.bank, g.abuf}, banks...)
	bufs = append(bufs, banks...)
	counts := []uint32{1, 1, 1, 1, 1, moeMaxBanks, moeMaxBanks}"""
new = """	// The last two bindings are **arrays** of moeMaxBanks descriptors, one a
	// layer, so the bindings are 5 + 2*48 + 1 = 102 buffers (L6a).
	//
	// **Binding 7 is the halves arena again, as sixteen-byte words** (P11):
	// the grouped GEMM's gathered A operand, eight halves a load instead of
	// one. The load addresses it by `uvec4` index, so the two offsets it
	// divides are the row stride and the arena base, and both have to be
	// whole loads — `lda` is `NEmbd + gemmPad` and every `halloc` rounds to
	// 64 elements, so they are, and this says so rather than trusting it.
	if g.lda%moeAVec != 0 || g.hXn%moeAVec != 0 {
		return fmt.Errorf("llm: the gathered operand loads %d halves at a time; lda %d and xn at %d are not whole loads",
			moeAVec, g.lda, g.hXn)
	}
	banks := g.bankSet()
	bufs := append([]*vk.Buffer{g.wbuf, g.abuf, g.hbuf, g.bank, g.abuf}, banks...)
	bufs = append(bufs, banks...)
	bufs = append(bufs, g.hbuf)
	counts := []uint32{1, 1, 1, 1, 1, moeMaxBanks, moeMaxBanks, 1}"""
assert old in s
s = s.replace(old, new)
open(p,'w').write(s)
PY
grep -n "moeMaxBanks =\|moeWave =\|moeBMMax" llm/gpu_moe.go | head -5

